import { mkdir, writeFile } from 'node:fs/promises';
import { join } from 'node:path';

export async function writeLocalAttribution(seedsDir, counts) {
  await mkdir(seedsDir, { recursive: true });
  const lines = [
    '# Exam bank seed attribution (local only — .local/ is gitignored)',
    '',
    'Generated by `npm run db:seed-exam-bank`.',
    '',
    '## Sources you may import',
    '',
    '| Source | License | Attribution |',
    '|--------|---------|-------------|',
    '| WeConnect catalogue | Your project | Internal starter content |',
    '| [CodePrep](https://codeprep.dev) | CC-BY-4.0 | Questions from CodePrep (https://codeprep.dev), CC-BY-4.0 |',
    '| [Coding_MCQs](https://github.com/alidevhere/Coding_MCQs) | MIT (repo) | Content scraped from Sanfoundry — verify their terms before production; items imported as `candidate` for review |',
    '| [Exercism problem-specifications](https://github.com/exercism/problem-specifications) | MIT | Exercism (https://exercism.org) |',
    '',
    '## This run',
    '',
    ...Object.entries(counts).map(([k, v]) => `- ${k}: ${v} items`),
    '',
    '## Can you use all of them for free?',
    '',
    '- **CodePrep**: Yes, with CC-BY attribution in your app/docs.',
    '- **Exercism**: Yes, MIT license.',
    '- **Your catalogue**: Yes.',
    '- **Coding_MCQs**: The **GitHub repo is MIT**, but the **questions originate from Sanfoundry**. For a university project, importing as review-only (`candidate`) is reasonable; for a commercial launch, get legal clarity or replace with your own AI-generated bank.',
    '',
  ];
  await writeFile(join(seedsDir, 'ATTRIBUTION.md'), lines.join('\n'), 'utf8');
}